-- Grants for lab role (created separately if missing)
DO  BEGIN
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'vvveb_lab') THEN
    CREATE ROLE vvveb_lab LOGIN PASSWORD 'CHANGE_ME_VVVEB_LAB';
  END IF;
END ;
GRANT USAGE ON SCHEMA vvveb TO vvveb_lab;
GRANT ALL ON ALL TABLES IN SCHEMA vvveb TO vvveb_lab;
GRANT ALL ON ALL SEQUENCES IN SCHEMA vvveb TO vvveb_lab;
ALTER DEFAULT PRIVILEGES IN SCHEMA vvveb GRANT ALL ON TABLES TO vvveb_lab;
ALTER DEFAULT PRIVILEGES IN SCHEMA vvveb GRANT ALL ON SEQUENCES TO vvveb_lab;
ALTER ROLE vvveb_lab SET search_path TO vvveb, public;

-- Lock down from PostgREST anon (lab tables are for CMS PHP only)
REVOKE ALL ON SCHEMA vvveb FROM anon, authenticated;
NOTIFY pgrst, 'reload schema';

